entries[193918] = { ["name"] = "Krug mit Glühwürmchen", ["text"] = "Questgegenstand\nBenutzen: Perfekt, um Frösche so lange abzulenken, dass Ihr sie einsammeln könnt. (3 Sek. Abklingzeit)\n70 ( 70)\n\"Ideal, um den Lieblingssnack eines Frosches griffbereit zu haben.\"" }
