entries[193922] = { ["name"] = "Wildstoff", ["text"] = "Handwerksmaterial\n\"Ein gut erhaltener Stoff, wie ihn die mächtigsten und seltensten Humanoiden der Dracheninseln tragen. Nützlich für Schneider.\"\nVerkaufspreis:" }
