entries[194021] = { ["name"] = "Verziertes Pergament: Untere Hälfte", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig\nBenutzen: Kombiniert die zwei Hälften des Pergaments zu einer Karte.\n\"Die linke Seite der Karte ist absolut unleserlich, bedeckt von einem dunklen Fleck, als ob jemand seine tintenverschmierte Hand absichtlich über den Bereich gezogen hat, um etwas zu verdecken.\"" }
entries[194022] = { ["name"] = "Verziertes Pergament: Obere Hälfte", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig\nBenutzen: Kombiniert die zwei Hälften des Pergaments zu einer Karte.\n\"Weitreichende Gewässer bedecken den oberen Bereich des Pergaments mit verschiedenen Vulkanabbildungen und sich hindurchschlängelnden Flüssen.\"" }
entries[194023] = { ["name"] = "Schatzkarte: Die Küste des Erwachens", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zeichnet auf der Karte der Küste des Erwachens die Positionen mehrerer Schätze ein.\n\"Der dunkle Fleck im unteren linken Bereich der Karte verbleibt. Was immer sich auch in dieser Gegend befindet, soll sicherlich nicht gefunden werden.\"" }
entries[194024] = { ["name"] = "Runengebundenes Pergament: Obere Hälfte", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig\nBenutzen: Kombiniert die zwei Hälften des Pergaments zu einer Karte.\n\"Sich schlängelnde Flüsse, gekennzeichnet mit großen, kopfförmigen Symbolen, sind über das Pergament verteilt.\"" }
entries[194025] = { ["name"] = "Runengebundenes Pergament: Untere Hälfte", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig\nBenutzen: Kombiniert die zwei Hälften des Pergaments zu einer Karte.\n\"Der Text unter der Karte ist größtenteils verblasst und nicht erkennbar. Eine große von Energie umwirbelte Säule erscheint in der unteren linken Ecke des Pergaments.\"" }
entries[194026] = { ["name"] = "Schatzkarte: Das Azurblaue Gebirge", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zeichnet auf der Karte des Azurblauen Gebirges die Positionen mehrerer Schätze ein.\n\"Sich schlängelnde Flüsse bedecken die Karte. Mehrere kopfförmige Symbole erscheinen an verschiedenen Orten. Eine überaus große von Energie umwirbelte Säule steht alleine im Südwesten.\"" }
entries[194027] = { ["name"] = "Uraltes Pergament: Obere Hälfte", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig\nBenutzen: Kombiniert die zwei Hälften des Pergaments zu einer Karte.\n\"Die obere linke Ecke ist vom Abdruck einer Scheibe gekennzeichnet. In der Mitte der Karte befindet sich ein großes, tempelähnliches Gebäude.\"" }
entries[194028] = { ["name"] = "Uraltes Pergament: Untere Hälfte", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig\nBenutzen: Kombiniert die zwei Hälften des Pergaments zu einer Karte.\n\"Die Tinte auf der Karte scheint sich zu bewegen, als schwarze Wirbel langsam durch eine Bergregion ziehen.\"" }
entries[194029] = { ["name"] = "Schatzkarte: Thaldraszus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zeichnet auf der Karte von Thaldraszus die Positionen mehrerer Schätze ein.\n\"Die herumwirbelnde Tinte verfestigt sich und eine große Fläche manifestiert sich mit einem großen, tempelähnlichen Gebäude in der Mitte, umringt von mehreren Gebäuden. In der oberen linken Ecke ist eine Scheibe mit geometrischen Formen zu sehen.\"" }
entries[194030] = { ["name"] = "Elchflanke", ["text"] = "Questgegenstand\n\"Ein bisschen zäh, aber vorzüglich für einen bei niedriger Temperatur gekochten Eintopf.\"" }
entries[194031] = { ["name"] = "Sturmberührte Splitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Gezackte Mineralien, die vor Energie knistern. Das Blut des Tieres, dem Ihr sie entrissen habt, klebt noch an ihnen.\"" }
