entries[194098] = { ["name"] = "Fürst Blattington", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[194099] = { ["name"] = "Jagdhorn der Shikaar", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Aktiviert für 15 Min. die Jagdausbildung, die Ihr von den Shikaar erhalten habt.\n\nNur im Freien auf den Dracheninseln verwendbar. (15 Min Abklingzeit)\nBenötigt Ruhmrang 23 bei den Zentauren der Maruuk und den Abschluss der Quest \"Auf zum Horn\"." }
entries[194102] = { ["name"] = "Ausgräber der Expedition", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Axt\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 25 / 25\nBenötigt Ruhmrang 7 bei der Drachenschuppenexpedition.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[194103] = { ["name"] = "Verrottende Probe", ["text"] = "Questgegenstand" }
entries[194105] = { ["name"] = "Welplingsformel", ["text"] = "Questgegenstand\n\"Eigens entwickelt, um Welplinge dabei zu unterstützen, zu starken und gesunden Drachen heranzuwachsen.\"" }
entries[194106] = { ["name"] = "Hochlanddrache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Hochlanddrachen oder gibt ihn wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Drachen des Azurblauen Gebirges folgen bei ihrer erneuten Erforschung der Inseln einem strengen Ehrenkodex.\"\nErfolg:\nDracheninseln: Hochlanddrache" }
entries[194108] = { ["name"] = "Horn des mächtigen Jägers", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stoßt in der Nähe des Machtbanners der Shikaar in dieses Horn, um die Wildnis herauszufordern. (15 Sek. Abklingzeit)" }
entries[194109] = { ["name"] = "Grünes Band der Dracthyr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+32 Ausdauer\nErhöht Eure Tempowertung um + 44.\n+ 62 Vielseitigkeit\nVerkaufspreis:" }
entries[194115] = { ["name"] = "Steinstatue", ["text"] = "Questgegenstand\n\"Aus Stein handgemeißelt, vielleicht ein Übungsstück.\"" }
entries[194118] = { ["name"] = "Truhe mit kosmischer Ausrüstung", ["text"] = "Saison 3 von Shadowlands\nWird an Kriegsmeute gebunden\nBenutzen: Erschafft ein Ausrüstungsteil des kosmischen Gladiators, das für Eure Beutespezialisierung nützlich ist." }
entries[194119] = { ["name"] = "Verzierter Schild", ["text"] = "Questgegenstand\n\"Zeigt mehr feine Details als die meisten Tuskarrwaffen, aber ist von den Jahren der Verwendung dennoch schwer beschädigt.\"" }
entries[194120] = { ["name"] = "Dekorative Teekanne", ["text"] = "Questgegenstand\n\"Ein schwerer Geruch von Seetang und Salz dringt aus dem Inneren.\"" }
entries[194121] = { ["name"] = "Handgefertigtes Boot", ["text"] = "Questgegenstand\n\"Dieses Boot wurde vorsichtig aus Mammutstoßzahn geschnitzt und seine Abnutzungsspuren zeigen, dass es viel Liebe erfahren hat.\"" }
entries[194122] = { ["name"] = "Saurer Apfel", ["text"] = "Benutzen: Wirft diesen sauren Apfel auf ein Ziel.\n\"Den sauren Geschmack wissen nur wenige zu schätzen.\"\nVerkaufspreis:" }
entries[194123] = { ["name"] = "Chromatischer Staub", ["text"] = "Handwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Verzauberkunst ausüben, indem sie Gegenstände entzaubern. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
