entries[194296] = { ["name"] = "Muster: Mit Drakoniumstoffschere spielen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man mit einer Drakoniumstoffschere spielt.\nDa Ihr Euer Handwerk gemeistert habt, stimuliert es vielleicht Euren Geist, wenn Ihr an Eurem Werkzeug herumtüftelt? Die einzige Garantie, die es dabei gibt, ist allerdings seine Zerstörung.\nBenötigt Schneiderei der Dracheninseln (50)\nVerkaufspreis:\nMit Drakoniumstoffschere spielen\n\"Was würde passieren, wenn dort Druck ausgeübt würde, während man hier zieht?\"\nBenötigt Federgetriebene Drakoniumstoffschere , Drakoniumnadelsatz" }
entries[194297] = { ["name"] = "Muster: Mit Khaz'goritstoffschere spielen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man mit einer Khaz'goritstoffschere spielt.\nDa Ihr Euer Handwerk gemeistert habt, stimuliert es vielleicht Euren Geist, wenn Ihr an Eurem Werkzeug herumtüftelt? Die einzige Garantie, die es dabei gibt, ist allerdings seine Zerstörung.\nBenötigt Schneiderei der Dracheninseln (50)\nVerkaufspreis:\nMit Khaz'goritstoffschere spielen\n\"Was würde passieren, wenn dort Druck ausgeübt würde, während man hier zieht?\"\nBenötigt Federgetriebene Khaz'goritstoffschere , Drakoniumnadelsatz" }
entries[194298] = { ["name"] = "Muster: Tristes Sargtuch", ["text"] = "Benutzen: Lehrt Euch, wie man ein tristes Sargtuch herstellt.\nBenötigt Schneiderei der Dracheninseln (45)\nVerkaufspreis:" }
entries[194299] = { ["name"] = "Flammendekoration", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+351 [Beweglichkeit oder Stärke]\nBenutzen: Stampft auf den Boden und lasst Flammen von Eurer Position ausstrahlen. Diese verursachen 30948 Feuerschaden, der auf alle getroffenen Gegner aufgeteilt wird, und gewähren Euch für 30 Sek. einen Schild in Höhe von 57788 . Nach einer Verzögerung kehren die Flammen zurück, verursachen den gleichen Schaden erneut und frischen den Schild auf.\n\nSchaden und Absorption werden für jeden getroffenen Gegner bis maximal 5 Gegner erhöht. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[194300] = { ["name"] = "Herbeigezauberte Frostkugel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+351 Intelligenz\nBenutzen: Wenn Euer Mana über 65% ist, wird die Frostkugel auf Euer Ziel geworfen und verursacht 55707 Frostschaden.\n\nWenn Euer Mana unter 65% ist, trinkt Ihr stattdessen von der Frostkugel, um sofort 4523 Mana wiederherzustellen. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[194301] = { ["name"] = "Flüsterndes Symbol der Inkarnation", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+371 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Gebt Euch dem Flüstern des Symbols hin und werdet mit Frost erfüllt, was Euren kritischen Trefferwert um 478 erhöht.\n\nWenn Ihr an der Seite von Verbündeten kämpft, die mit Erde oder Feuer erfüllt sind, besteht eine Chance, dass Ihr 12 Sek. lang 131 des Werts ihrer jeweiligen Infusion erhaltet.\n\nDie Infusion ist von Eurer aktuellen Spezialisierung abhängig. (1.5s Abklingzeit)\nVerkaufspreis:" }
entries[194302] = { ["name"] = "Segen der Sturmfresserin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+371 [Beweglichkeit oder Stärke]\nBenutzen: Nehmt den Sturm an und werdet für 10 Sek. zu einem unbeweglichen Urluftelementar.\n\nIn dieser Gestalt fügen die Winde um Euch allen Gegnern innerhalb von 10 Metern pro Sekunde 6309 Naturschaden zu, der sich pro Sekunde um 10% erhöht, bis die Verwandlung endet. (3 Min Abklingzeit)\nVerkaufspreis:" }
entries[194303] = { ["name"] = "Rasselnder Rubin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+351 Stärke\nAnlegen: Eure Angriffe bauen langsam Stapel von 'Erschütternde Kraft' auf, die Euch pro Stapel 21 Angriffskraft gewähren.\n\nBei 10 Stapeln entfesseln Eure nächsten 3 Nahkampffähigkeiten eine Schockwelle vor Euch, die allen Gegnern in einer Linie zusätzlich 16542 Naturschaden zufügt. Die Schockwellen fügen Gegnern mit hoher Gesundheit mehr Schaden zu. (500ms Abklingzeit)\nVerkaufspreis:" }
entries[194304] = { ["name"] = "Eisbluttodesfessel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+351 Intelligenz\nBenutzen: Fügt Eurem Ziel 40232 Frostschaden zu und wickelt es sowie Gegner in der Nähe für 15 Sek. in ein Kristallnetz. Im Netz gefangene Gegner sind um 15% verlangsamt und erleiden 3185 Frostschaden, wenn ein Gegner im Netz getroffen wird.\n\nDer Schaden erhöht sich für jeden im Netz gefangenen Gegner, bis zu 5 Gegner. Der Schaden pro Ziel ist bei mehr als 5 Gegnern verringert. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[194305] = { ["name"] = "Kontrollierte Strömungstechnik", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+371 Beweglichkeit\nAnlegen: Eure kritischen Treffer haben eine Chance, 'Statische Elektrizität' aufzubauen, was Euer Angriffstempo pro Stapel um 2% erhöht. Dieser Effekt kann einmal alle 1 Sek. auftreten.\n\nBei 10 Stapeln fährt ein Blitz durch Euch, der Eure Bewegungsgeschwindigkeit für 12 Sek. um 30% erhöht. Während Ihr vom Blitz ergriffen seid, schocken Eure automatischen Angriffe Euer Ziel und 1 weiteren Gegner in der Nähe und fügen ihnen 6470 Naturschaden zu.\n\nWenn dieser Effekt nachlässt, werdet Ihr für 1 Min. geerdet und könnt nicht erneut 'Statische Elektrizität' aufbauen. (1.5s Abklingzeit)\nVerkaufspreis:" }
entries[194306] = { ["name"] = "Alltotem des Meisters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+371 [Beweglichkeit oder Stärke]\nAnlegen: Nehmt eine Elementarhaltung ein. Wenn Ihr einem Angriff erfolgreich ausweicht oder ihn pariert, entfesselt Ihr auf Gegner vor Euch einen mächtigen Elementargegenangriff, während Ihr die nächste Haltung einnehmt.\n\nDieser Effekt kann nur einmal alle 30 Sek. auftreten. (30s Abklingzeit)\nVerkaufspreis:" }
entries[194307] = { ["name"] = "Versprechen der Bruthüterin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 Intelligenz\nBenutzen: Wählt einen Spielercharakter aus, mit dem Ihr eine Bindung eingehen möchtet, und werdet für 1 Stunde zu seinem Wächter.\n\nWährend Ihr verbunden seid, erhaltet Ihr und Euer Verbündeter [Quellwert] Vielseitigkeit und stellt pro Sekunde [Quellwert] Gesundheit wieder her. Solange Ihr Euch innerhalb von 15 Metern zueinander aufhaltet, werden diese Boni erhöht.\n\nGilt nur für Heilerspezialisierungen. (5 Sek. Abklingzeit)\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[194308] = { ["name"] = "Manische Trauerfackel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 [Beweglichkeit oder Stärke]\nBenutzen: Kanalisiert für 2 Sek. und entfesselt eine wilde Salve aus Flammen um Euer Ziel herum, die ihm bis zu [ 20285 * (8) * (1 + Vielseitigkeit)] Feuerschaden zufügt und eine Chance hat, zusätzlich Gegnern in der Nähe Schaden zuzufügen.\n\nDurch den Tod eines verbündeten Spielercharakters wird die Abklingzeit um 90 Sek. verringert. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[194309] = { ["name"] = "Boshafter Sturm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Der Einsatz von Zaubern und Fähigkeiten erzeugt Stapel von Bosheit. Bei 5 Stapeln springt ein 'Boshafter Sturmblitz' auf Eurer anvisiertes Ziel über und verursacht im Verlauf von 3 Sek. [ 1828 * (6) * (1 + Vielseitigkeit)] Naturschaden.\n\nBei Ablauf kehrt der Blitz zurück, erhöht die benötigten Stapel von Bosheit um 1 und erhöht den dem Ziel durch 'Boshafter Sturmblitz' zugefügten Schaden permanent, bis einer von Euch stirbt. (1s Abklingzeit)\nVerkaufspreis:" }
entries[194310] = { ["name"] = "Kodex des verzweifelten Herbeirufers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+382 Intelligenz\nAnlegen: Das Wirken von Zaubern gewährt Stapel von Hass, durch die die Abklingzeit dieses Schmuckstücks bis zum Ende des Kampfes um 1 Sek. verringert wird. Dieser Effekt ist bis zu 180-mal stapelbar. (1s Abklingzeit)\nBenutzen: Entfesselt gefährliche Blitze und fügt Eurem Ziel 125328 Naturschaden und Euch 665 Naturschaden zu. Der Euch selbst zugefügte Schaden wird durch Stapel von Hass erhöht. (4 Min Abklingzeit)\nVerkaufspreis:" }
entries[194311] = { ["name"] = "Muster: Sitzsack der Tuskarr", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Sitzsack der Tuskarr herstellt.\nBenötigt Lederverarbeitung der Dracheninseln (50)\nBenötigt Ruhmrang 23 bei den Tuskarr von Iskaara.\nVerkaufspreis:" }
