entries[194421] = { ["name"] = "Teeras Bogen", ["text"] = "Questgegenstand\n\"Dieser Bogen gehörte Teera, der Gründerin des Klans Teerai, und wurde beim Angriff der Nokhud dazu verwendet, ihren Geist zurückzubringen.\"" }
