entries[194423] = { ["name"] = "Maruuks Speer", ["text"] = "Questgegenstand\n\"Der Speer von Maruuk Tausendknochen, der ursprünglich die Zentauren zu den Dracheninseln führte. Die Ukhel nutzten ihn, um seinen Geist zu beschwören und ihn als Waffe zu kontrollieren.\"" }
entries[194424] = { ["name"] = "Stoßzahnmark", ["text"] = "Questgegenstand" }
entries[194425] = { ["name"] = "Flachlandeberrippchen", ["text"] = "Questgegenstand\n\"Diese fleischigen Rippen KRACHEN laut, wenn ein Metzger sie aus dem Brustkorb bricht. Igitt.\"" }
entries[194426] = { ["name"] = "Angereicherte Erde", ["text"] = "Wird beim Aufheben gebunden\nDauer: 30 min (Realzeit)\nBenutzen: Verteilt die Erde auf dem Boden und fördert das Wachstum von Pflanzen in der Nähe.\nVerkaufspreis:" }
entries[194427] = { ["name"] = "Gorlocschleim", ["text"] = "Questgegenstand" }
entries[194430] = { ["name"] = "Krakles Auslöserpfote", ["text"] = "Questgegenstand\n\"Verantwortlich für den Tod abertausender kleiner Waldtiere.\"" }
entries[194431] = { ["name"] = "Leykristall", ["text"] = "Questgegenstand\n\"Der Kristall flackert, als wäre sogar die darin gespeicherte Magie vom Verfall besudelt.\"" }
entries[194432] = { ["name"] = "Hauer vom alten Steinhauer", ["text"] = "Questgegenstand\n\"Das traurigste Stück Elfenbein, das Ihr je gesehen habt.\"" }
entries[194433] = { ["name"] = "Bluthorns Horn", ["text"] = "Questgegenstand\n\"Befleckt mit dem Blut der Unklugen und Unglücklichen.\"" }
entries[194434] = { ["name"] = "Stechende Salbe", ["text"] = "Questgegenstand\nBenutzen: Für Hornschreiter. Dick auftragen, um Wunden zu lindern. (2 Sek. Abklingzeit)\n\"Dieses Gemisch wurde speziell für Hornschreiter hergestellt und riecht streng nach Fisch.\"" }
