entries[194437] = { ["name"] = "Ursprüngliches Ritual", ["text"] = "Questgegenstand" }
entries[194439] = { ["name"] = "Frostfausts Auge", ["text"] = "Questgegenstand\n\"Ein unglaublich klarer und kalter Klumpen Eis. Er will einfach nicht schmelzen.\"" }
entries[194440] = { ["name"] = "Yetors Kopf", ["text"] = "Questgegenstand\n\"Der blutige Kopf grinst oder schneidet Grimassen, je nach Blickwinkel.\"" }
entries[194441] = { ["name"] = "Wasserelementarflasche", ["text"] = "Questgegenstand\nBenutzen: Entfesselt einen Wasserelementar am Zielort oder heilt einen bereits entfesselten Wasserelementar vollständig und erhöht seinen verursachten Schaden. (30 Sek. Abklingzeit)\n\"Ein kostbares Werkzeug der Drachenbrut, die sich um Lavaelementare kümmert.\"" }
