entries[194503] = { ["name"] = "Pläne: Schwarzdrachenberührter Hammer", ["text"] = "Benutzen: Lehrt Euch, wie man einen schwarzdrachenberührten Hammer herstellt.\nFindet die Schmiede des Erdwächters in der Drachenfluchfestung im Westen der Küste des Erwachens.\nBenötigt Schmiedekunst der Dracheninseln (50)\nVerkaufspreis:" }
