entries[194509] = { ["name"] = "Quellgeborener Kern", ["text"] = "Questgegenstand\n\"Ein mächtiger Elementarkern, der sich in den Wassern einer heißen Quelle geformt hat.\"" }
entries[194510] = { ["name"] = "Harpune von Iskaara", ["text"] = "Benutzen: Wendet Euch einem \"Oschi\" zu und werft! (4 Sek. Abklingzeit)" }
entries[194511] = { ["name"] = "Lebende Verpflegung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[194512] = { ["name"] = "Defektes arkanes Gerät", ["text"] = "Questgegenstand\n\"Etwas arkane Magie sprüht immer noch aus diesem Teil des Geräts.\"" }
entries[194513] = { ["name"] = "Foliantensammlung", ["text"] = "Questgegenstand\n\"Diese Folianten schildern detailliert, wie des Lager Antonidas vor 10.000 Jahren war.\"" }
entries[194514] = { ["name"] = "Antiquierte Gästeliste", ["text"] = "Questgegenstand\n\"In diesem alten Folianten stehen die Namen von Drachen, die diese Gegend besucht haben. Zwei Namen sind auf fast jeder Seite: Malygos und Sindragosa.\"" }
entries[194515] = { ["name"] = "Zerbröckelnder Ereigniskalender", ["text"] = "Questgegenstand\n\"Dieses Buch schildert detailliert verschiedene Ereignisse, die in dieser Gegend stattgefunden haben. Alle schienen mit Zurschaustellungen von Arkana für andere Drachenschwärme und Aspekte einherzugehen.\"" }
entries[194516] = { ["name"] = "Gealtertes Tagebuch", ["text"] = "Questgegenstand\n\"Auf diesen Seiten finden sich Details über die Balz zweier blauer Drachen, Malygos und Sindragosa. Eine Anmerkung deutet darauf hin, dass es \"Teil eins einer Serie\" sei.\"" }
entries[194517] = { ["name"] = "Bruchstückhafte Texte", ["text"] = "Questgegenstand\n\"Dieses Buch schildert detailliert die Drakoniden und Drachenbrut, die sich um diese Gegend gekümmert haben, nachdem die blauen Drachen verschwunden sind. Auf vielen Seiten wird beklagt, dass auch die \"Freude\" mit dem Weggang von Sindragosa und Malygos verloren ging.\"" }
entries[194519] = { ["name"] = "Osorias Unterstützung", ["text"] = "Questgegenstand\nBenutzen: Ruft Osoria, um Euch in die Lüfte zu tragen und Gegner anzugreifen. Nur in der Obsidianzitadelle. (5 Sek. Abklingzeit)\n70 ( 70)" }
entries[194520] = { ["name"] = "Schriftrolle des Wissens der Zeitwanderer", ["text"] = "Questgegenstand\n\"Die Schriftrolle beinhaltet eine Fülle an Wissen über Zeitmagie. Ihr spürt, wie sie Eure Gedanken verzerrt, wenn Ihr das Pergament zu lange anstarrt.\"" }
entries[194521] = { ["name"] = "Klippenwilddrache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Klippenwilddrachen oder gibt ihn wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Sie nisten häufig an den steilen Klippen von Thaldraszus und steigen bei Gefahr schnell in den Himmel auf.\"\nErfolg:\nDracheninseln: Klippenwilddrache" }
entries[194522] = { ["name"] = "Blauer Stab des Schwingenfürsten", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n5 - 8 Schaden Geschwindigkeit 3.60\n(1.8 Schaden pro Sekunde)\n+22 Intelligenz\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 6.\nHaltbarkeit 85 / 85\nKlassen: Rufer\nVerkaufspreis:" }
