entries[194533] = { ["name"] = "Blauer Ring des Schwingenfürsten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 9.\n+ 5 Vielseitigkeit\nKlassen: Rufer\nVerkaufspreis:" }
