entries[194535] = { ["name"] = "Kobaltblauer Umhang des Schwingenfürsten", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 3.\nKlassen: Rufer\nVerkaufspreis:" }
entries[194536] = { ["name"] = "Blaues Amulett des Schwingenfürsten", ["text"] = "Wird beim Aufheben gebunden\nHals\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 10.\nKlassen: Rufer\nVerkaufspreis:" }
entries[194537] = { ["name"] = "Mit Drakoniumstoffschere spielen", ["text"] = "\"Was würde passieren, wenn dort Druck ausgeübt würde, während man hier zieht?\"" }
entries[194538] = { ["name"] = "Mit Khaz'goritstoffschere spielen", ["text"] = "\"Was würde passieren, wenn dort Druck ausgeübt würde, während man hier zieht?\"" }
entries[194540] = { ["name"] = "Notizen des Rüstungsschmieds der Nokhud", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zeichnet auf Eurer Karte die Position eines Schatzes auf den Ebenen von Ohn'ahra ein.\n\"Die Lieferung ist bereit. Eure Waffen werden bis zu Eurer Rückkehr in der Festung verwahrt. - Graath\"" }
entries[194541] = { ["name"] = "Prototyprahmen für ein majestätisches Geschirr", ["text"] = "Handwerksmaterial\n\"Wird von Spielercharakteren hergestellt, die den Beruf Schmiedekunst ausüben. Kann durch Handwerksaufträge erworben werden.\"\nVerkaufspreis:" }
entries[194542] = { ["name"] = "Prototyprahmen für ein Geschirr des Forschers", ["text"] = "Handwerksmaterial\n\"Wird von Spielercharakteren hergestellt, die den Beruf Schmiedekunst ausüben. Kann durch Handwerksaufträge erworben werden.\"\nVerkaufspreis:" }
entries[194544] = { ["name"] = "Flammenklinge des Erdwächters", ["text"] = "Questgegenstand\n\"Eine mächtige Waffe, die Drachkin einst in die Schlacht führten.\"" }
entries[194545] = { ["name"] = "Prismatisches Erz", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Spezialisierte Juwelenschleifer erhalten dies beim Sondieren von Erz auf den Dracheninseln. Das Sondieren verspricht, einen ganzen Haufen Edelsteine zu ergeben.\"\nVerkaufspreis:" }
entries[194546] = { ["name"] = "Baskilans Bericht", ["text"] = "Questgegenstand\n\"Beobachtungen, die ausführlich beschreiben, wie die Djaradin Hornstachelfleisch ernten.\"" }
entries[194548] = { ["name"] = "Urzeitlicher geschmolzener Kern", ["text"] = "Questgegenstand\nEinzigartig\n\"Brennt bei Berührung, doch verweigert den Flammen, sich auszubreiten.\"" }
entries[194549] = { ["name"] = "Windgeborener Velocidrache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren windgeborenen Velocidrachen oder gibt ihn wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die langen Krallen des Velocidrachen verleihen ihm einen Vorteil auf den Ebenen.\"\nErfolg:\nDracheninseln: Windgeborener Velocidrache" }
entries[194550] = { ["name"] = "Kaltbisspfeilblatt", ["text"] = "Questgegenstand" }
entries[194551] = { ["name"] = "Würziges Lavagewürz", ["text"] = "Questgegenstand" }
entries[194552] = { ["name"] = "Glimmende Wandertangknolle", ["text"] = "Questgegenstand" }
entries[194553] = { ["name"] = "Zeitversengter Trüffler", ["text"] = "Questgegenstand" }
entries[194554] = { ["name"] = "Pikanter Deviantbandfisch", ["text"] = "Questgegenstand\n\"Ein köstlicher, uralter Verwandter.\"" }
entries[194555] = { ["name"] = "Wilder Springmais", ["text"] = "Questgegenstand" }
entries[194556] = { ["name"] = "Brisenjägerei", ["text"] = "Questgegenstand\n\"Das unbefruchtete Ei eines Brisenjägers aus den Ebenen von Ohn'ahra. Das habt Ihr nicht wirklich unversehrt eingesammelt!\"" }
entries[194559] = { ["name"] = "Vazallias Bericht", ["text"] = "Questgegenstand\n\"Eine Karte, die die Front des von den Djaradin kontrollierten Lavastroms zeigt.\"" }
entries[194561] = { ["name"] = "Zepharions Bericht", ["text"] = "Questgegenstand\n\"Ein Bericht, der die Anzahl der Djaradin, die an der Drachenfluchfestung lagern, ausführlich beschreibt.\"" }
entries[194562] = { ["name"] = "Gelegentlicher Sand", ["text"] = "\"Gelegentlich ist es. Und wenn es ist, ist es Sand.\"\nVerkaufspreis:" }
entries[194564] = { ["name"] = "Extraleckeres Flussbestienfleisch", ["text"] = "Questgegenstand\n\"Ein zartes, fettes Stück Flussbestienfleisch voller Nährstoffe, ausgezeichnet auf die winzigen Zähne und komplexen Bedürfnisse der Protowelpen zugeschnitten.\"" }
entries[194565] = { ["name"] = "Steinerne Ponoliakstatue", ["text"] = "Questgegenstand\n\"Eine grob gehauene Steinbüste, die den kürzlich verstorbenen Tuskarrhäuptling Ponoliak darstellt. Sie wurde offensichtlich herumgeschleudert und ist mit frischem Speichel bedeckt.\"" }
