entries[194696] = { ["name"] = "Wiederverwertete Kriechermine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nDauer: 4 std.\nBenutzen: Setzt eine Kriechermine ein, die Euch unterstützt.\n\nKann innerhalb der Obsidianzitadelle und der angrenzenden Lavafelder verwendet werden. (1 Min Abklingzeit)\n\"Explodiert genauso gut wie neue Kriecherminen!\"\nVerkaufspreis:" }
entries[194697] = { ["name"] = "Drakonische Alchemieabhandlung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 1 zu erhöhen.\nBenötigt Alchemie der Dracheninseln\n(25)\n\"Enthält Notizen über verschiedene Berufsgeheimnisse von Alchemisten. Kann nur einmal pro Woche gelesen werden.\"\nVerkaufspreis:" }
