entries[194701] = { ["name"] = "Ominöse Muschel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Setzt 5 ominöse Muscheln in der Nähe einer Position ein, an der ein großer Oschi der Tuskarr gesichtet wurde, um einen GROSSEN Oschi zu beschwören..." }
