entries[194703] = { ["name"] = "Drakonische Juwelierskunstabhandlung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Juwelierskunstwissen der Dracheninseln um 1 zu erhöhen.\nBenötigt Juwelierskunst der Dracheninseln\n(25)\n\"Enthält Notizen über verschiedene Berufsgeheimnisse von Juwelenschleifern. Kann nur einmal pro Woche gelesen werden.\"\nVerkaufspreis:" }
