entries[194705] = { ["name"] = "Hochlanddrache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Hochlanddrachen oder gibt ihn wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Drachen des Azurblauen Gebirges folgen bei ihrer erneuten Erforschung der Inseln einem strengen Ehrenkodex.\"\nErfolg:\nDracheninseln: Hochlanddrache" }
entries[194707] = { ["name"] = "Myridians Bericht", ["text"] = "Questgegenstand\n\"Beobachtungen, die die Bewegungen des Weltenbrecher-Klans ausführlich beschreiben.\"" }
