entries[194730] = { ["name"] = "Schuppenbauchmakrele", ["text"] = "Benutzen: Wirft den Fisch zurück ins Wasser, um Eure Angelfertigkeit 30 Sek. lang um 5 zu erhöhen.\n\nDurch das Zurückwerfen mehrerer Fische kann diese Stärkung auf bis zu 5 Min. verlängert werden.\nHandwerksmaterial\n\"Ein gewöhnlicher Fisch, der überall auf den Dracheninseln heimisch ist. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
