entries[194747] = { ["name"] = "Gefrorene Giftdrüse", ["text"] = "Questgegenstand\n\"Das gifterzeugende Organ einer riesigen Spinne. Die Tuskarr sind dafür bekannt, daraus ein wirksames Mittel gegen Spinnengift anzurühren.\"" }
