entries[194818] = { ["name"] = "Protodrachenbändigerseil", ["text"] = "Questgegenstand\nBenutzen: Bändigt einen geschwächten wilden Protodrachen, sodass er Euch 5 Min. lang folgt. (3 Sek., 500 Ms Abklingzeit)" }
entries[194827] = { ["name"] = "Kartenbündel: Dracheninseln", ["text"] = "Benutzen: Aufreißen, um Dunkelmondkarten zu erhalten! Enthält nur Karten, die von den Dracheninseln stammen.\nHandwerksmaterial\nVerkaufspreis:" }
entries[194829] = { ["name"] = "Schicksalhafte Glückskarte", ["text"] = "Benutzen: Dreht eine Karte um, um in die Zukunft zu sehen.\nVerkaufspreis:" }
entries[194838] = { ["name"] = "Manuskript: Hochlanddrache: Dornenkopf" }
entries[194842] = { ["name"] = "Manuskript: Majestätisches Geschirr" }
entries[194843] = { ["name"] = "Manuskript: Geschirr des Forschers" }
entries[194872] = { ["name"] = "Dunkelmondkartensetschachtel: Inferno", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Dunkelmond-Kartenset (1)\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Anlegen: Mischt im Kampf regelmäßig das Kartenset.\nBenutzen: Benutzen: Schleudert ein schwelendes Inferno auf das Ziel, das ( 62055 * .3)- 62055 Feuerschaden verursacht. Der Schaden wird von der obenliegenden Karte des Kartensets bestimmt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[194874] = { ["name"] = "Befestigter Federkiel des Schreibers", ["text"] = "Wird beim Anlegen gebunden\nWerkzeug für Inschriftenkunde + 80 Zufallswert 1\nAnlegen: +6 Fertigkeit in Inschriftenkunde der Dracheninseln\n\"Diese Feder dient als Ersatz für ein Schreibzeug des Virtuosen.\"\nVerkaufspreis:" }
entries[194875] = { ["name"] = "Prächtiger Federkiel des Schreibers", ["text"] = "Wird beim Aufheben gebunden\nWerkzeug für Inschriftenkunde + 125 Zufallswert 1\nAnlegen: +10 Fertigkeit in Inschriftenkunde der Dracheninseln\n\"Diese Feder dient als Ersatz für ein Schreibzeug des Virtuosen.\"\nVerkaufspreis:" }
entries[194877] = { ["name"] = "Kompendium des Kernforschers", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+149 Intelligenz\n+73 Ausdauer\n+ 49 Zufallswert 1\n+ 49 Zufallswert 2\nVerkaufspreis:" }
entries[194879] = { ["name"] = "Knisternder Kodex der Inseln", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+394 Intelligenz\n+208 Ausdauer\n+ 120 Zufallswert 1\n+ 120 Zufallswert 2\nVerkaufspreis:" }
entries[194883] = { ["name"] = "Runenflügel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[194884] = { ["name"] = "Nerv-o-Tron-Bande", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nDauer: 4 std.\nBenutzen: Lässt nervige Roboter auf ein Gebiet los, um dort 30 Sek. lang alle Gegner aufzudecken und abzulenken.\n\nKann innerhalb der Obsidianzitadelle und der angrenzenden Lavafelder verwendet werden. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[194885] = { ["name"] = "Ohunastange", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert eine Stange, um ein Kind von Ohn'ahra in der Nähe anzulocken. Der Ohuna wird 10 Min. lang Post abholen und bringen, oder bis er weggerufen wird. (3 Std. Abklingzeit)" }
entries[194886] = { ["name"] = "Tazenraths gerissener Flügel", ["text"] = "Wird beim Aufheben gebunden\n\"Die aufgedruckten Runen sind verblasst.\"\nVerkaufspreis:" }
entries[194887] = { ["name"] = "Schrottfalle", ["text"] = "Wird beim Aufheben gebunden\nDauer: 4 std.\nBenutzen: Wirft eine Schrottfalle auf den Boden, die explodiert, sobald ein Gegner auf sie tritt, und dabei 25 Feuerschaden verursacht.\n\nKann in der Obsidianzitadelle und auf den benachbarten Lavafeldern verwendet werden. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[194888] = { ["name"] = "Gravierte Dracthyrklinge", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n20 - 35 Schaden Geschwindigkeit 2.60\n(10.6 Schaden pro Sekunde)\n+19 Intelligenz\n+28 Ausdauer\nErhöht Eure kritische Trefferwertung um + 20.\nErhöht Eure Tempowertung um + 17.\nHaltbarkeit 90 / 90\nVerkaufspreis:" }
entries[194889] = { ["name"] = "Baukasten für Lenkrakete XD-57 \"Volltreffer\"", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 4 std. (Realzeit)\nBenutzen: Baut eine Rakete, die ungehindert fliegen kann und 1 Min. lang bestehen bleibt.\n\nKann innerhalb der Obsidianzitadelle und der angrenzenden Lavafelder verwendet werden. (5 Sek. Abklingzeit)\n5 Aufladungen\n\"Ab 5 Jahren und älter.\"\nVerkaufspreis:" }
entries[194890] = { ["name"] = "Mikrojetpack GG-117", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 4 std. (Realzeit)\nBenutzen: Lässt Euren Sprung feurig werden. Fügt Gegnern am Einschlagsort Feuerschaden zu und stößt sie zu Boden.\n\nKann innerhalb der Obsidianzitadelle und der angrenzenden Lavafelder verwendet werden. (1.5s Abklingzeit) (10 Sek. Abklingzeit)\n5 Aufladungen\n\"Vorsicht: Vom Gesicht weg zielen.\"\nVerkaufspreis:" }
entries[194891] = { ["name"] = "Arkaner Haken", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Nutzt Arkanmagie, um einen Wyrm 80 Meter wegzuziehen. (5 Sek. Abklingzeit)" }
entries[194892] = { ["name"] = "Krümmrindenstab des Pioniers", ["text"] = "Wird beim Anlegen gebunden\nZweihändig Stab\n184 - 342 Schaden Geschwindigkeit 3.60\n(73.1 Schaden pro Sekunde)\n+97 Beweglichkeit\n+146 Ausdauer\n+ 97 Zufallswert 1\n+ 97 Zufallswert 2\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[194893] = { ["name"] = "Krümmrindenstab des Aufsehers", ["text"] = "Wird beim Anlegen gebunden\nZweihändig Stab\n111 - 151 Schaden Geschwindigkeit 3.60\n(36.4 Schaden pro Sekunde)\n+432 Intelligenz\n+146 Ausdauer\n+ 97 Zufallswert 1\n+ 97 Zufallswert 2\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[194894] = { ["name"] = "Stab des verwitterten Forschers", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n243 - 452 Schaden Geschwindigkeit 3.60\n(96.5 Schaden pro Sekunde)\n+1.142 Intelligenz\n+416 Ausdauer\nHaltbarkeit 120 / 120\nAnlegen: Beim Verursachen von Schaden besteht eine Chance, dass Ihr von einer Woge vertrauter Energie erfüllt werdet, die Euer Tempo 15 Sek. lang um 1578 erhöht.\nVerkaufspreis:" }
entries[194897] = { ["name"] = "Kinetische Säule der Inseln", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n487 - 905 Schaden Geschwindigkeit 3.60\n(193.3 Schaden pro Sekunde)\n+257 Beweglichkeit\n+416 Ausdauer\n+ 239 Zufallswert 1\n+ 239 Zufallswert 2\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[194898] = { ["name"] = "Erhellende Säule der Inseln", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n295 - 400 Schaden Geschwindigkeit 3.60\n(96.5 Schaden pro Sekunde)\n+1.142 Intelligenz\n+416 Ausdauer\n+ 239 Zufallswert 1\n+ 239 Zufallswert 2\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[194899] = { ["name"] = "Zauberstab der Verbannung", ["text"] = "Questgegenstand\n\"Dieser Zauberstab wurde von den Kirin Tor speziell für ihre Exkursion ins Azurblaue Gebirge entwickelt. Er kann kleine Felder instabiler arkaner Energie bannen.\"" }
entries[194900] = { ["name"] = "Miva's Zauberstab der Verbannung", ["text"] = "Questgegenstand\n\"Dieser Zauberstab wurde von den Kirin Tor speziell für ihre Exkursion ins Azurblaue Gebirge entwickelt. Er kann kleine Felder instabiler arkaner Energie bannen.\"" }
entries[194901] = { ["name"] = "Gekrümmte Hörner", ["text"] = "Questgegenstand\n\"Diese robusten Hörner haben über die Jahre viele Schlachten überstanden.\"" }
entries[194902] = { ["name"] = "Weichgeschmolzene Schokolade", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 tag\nVerkaufspreis:" }
entries[194903] = { ["name"] = "Taschenschokolade", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 tag (Realzeit)\nBenutzen: Verspeist die mit Fusseln übersäte Köstlichkeit und stellt 5 Sek. lang 20% Gesundheit und Mana wieder her.\n\"Nicht vergessen: Schokolade schmilzt.\"" }
entries[194961] = { ["name"] = "Gestohlener Raketensprung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 4 std.\nBenutzen: Legt den gestohlenen Raketensprung an. (10 Sek. Abklingzeit)\n\"Gestohlene SI:7-Ausrüstung, die es irgendwie hierher geschafft hat.\"\nVerkaufspreis:" }
entries[194963] = { ["name"] = "Pläne: Obsidianversengte Legierung", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man eine obsidianversengte Legierung herstellt.\nFindet die Schmiede des Erdwächters in der Drachenfluchfestung im Westen der Küste des Erwachens.\nBenötigt Schmiedekunst der Dracheninseln (50)\nVerkaufspreis:" }
entries[194964] = { ["name"] = "Rezept: Dreifachgewürzter Mammutkebap", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dreifachgewürzten Mammutkebap zubereitet.\nRezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab.\nBenötigt Kochkunst der Dracheninseln (25)" }
entries[194965] = { ["name"] = "Rezept: Yusas herzhafter Eintopf", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Yusas herzhaften Eintopf zubereitet.\nRezept für 2 Festmahle. Die tatsächliche Anzahl an Festmahlen hängt von Eurer Kochfertigkeit ab.\nBenötigt Kochkunst der Dracheninseln (30)" }
entries[194966] = { ["name"] = "Tausendbisspiranha", ["text"] = "Handwerksmaterial\n\"Ein gewöhnlicher Fisch, der in Süßgewässern auf den Dracheninseln heimisch ist. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[194967] = { ["name"] = "Querflossen-Flügelrossfisch", ["text"] = "Handwerksmaterial\n\"Ein gewöhnlicher Fisch, der in Salzgewässern auf den Dracheninseln heimisch ist. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[194968] = { ["name"] = "Himmelblauer Stachelfisch", ["text"] = "Handwerksmaterial\n\"Ein gewöhnlicher Fisch, der in Salzgewässern auf den Dracheninseln heimisch ist. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[194969] = { ["name"] = "Temporaler Drachenkopf", ["text"] = "Handwerksmaterial\n\"Ein gewöhnlicher Fisch, der in Süßgewässern auf den Dracheninseln heimisch ist. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[194970] = { ["name"] = "Inselfinnenschwertfisch", ["text"] = "Handwerksmaterial\n\"Ein scheuer Fisch, der auf den Dracheninseln heimisch ist. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[194971] = { ["name"] = "Kristallisiertes Drakonium", ["text"] = "Questgegenstand\n\"Kristallisiertes Drakonium, das sich unter großem Druck geformt hat.\"" }
entries[194973] = { ["name"] = "Gemischressourcen zurückgewinnen", ["text"] = "\"Extrahiert eine alchemistische Lösung des Drachen aus einer großen Menge nicht benötigter Tränke oder Phiolen.\"" }
entries[195041] = { ["name"] = "Ewiglebender Holzschlüssel", ["text"] = "Wird beim Aufheben gebunden\n\"Wenn der Schlüssel Schaden erleidet, wächst die Stelle einfach nach.\"" }
entries[195042] = { ["name"] = "Reparierter Titanenstab", ["text"] = "Questgegenstand\n\"Irgendwie immer noch so robust und zuverlässig wie am Tag seiner Fertigung.\"" }
entries[195044] = { ["name"] = "Noch mal versuchen", ["text"] = "Questgegenstand\nBenutzen: Beginnt Euren Versuch zu segeln erneut. (10 Sek. Abklingzeit)" }
